INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13249, 'koKR', 'Dowód zgonu: Prorok Tharon\'ja', 'Twierdza Drak\'Tharon była niegdyś dumnym bastionem narodu Drakkari. Teraz to tylko przyczółek Króla Lisza w walce, która ma położyć kres Zul\'Drakowi i wydrzeć moc trollowym bogom.$B$BJeśli jednak zgładzimy ich przywódcę, Proroka Tharon\'ję, może zdołamy powstrzymać napływ trollowych posiłków Plagi. W najgorszym razie Krucjata Argentu w Zul\'Draku będzie miała o jedno zmartwienie mniej.$B$BPrzynieś mi jego tiki, żebym wiedział, że prorok nie żyje.', 'Arcymag Lan\'dalock w Dalaranie chce, żebyś $gwrócił:wróciła; z Zaczarowanym tiki proroka.$B$BTo zadanie można wykonać tylko na poziomie heroicznym.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13249, 'koKR', 'Przy odrobinie szczęścia Twierdza Drak\'Tharon, pozbawiona przywódcy, nie będzie już takim cierniem w boku tych, którzy walczą w tym regionie z Plagą.$b$b<Arcymag spogląda na tiki w twojej dłoni.>$b$bI dobrze, że tiki straciło swoje mojo. Nie miałbym pojęcia, jak go użyć, ani nawet czy wypada robić coś takiego.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13249, 'koKR', '$GStanąłeś:Stanęłaś; do walki z prorokiem? Masz tiki?', 0);
