INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(26464, 'koKR', 'Powstańcie, moi wojownicy, i walczcie dla nowego pana!', '', 0),
(26473, 'koKR', 'Miłego towarzystwa! Król Lisz przesyła pozdrowienia!', '', 0),
(26474, 'koKR', 'Nie uciekajcie tak szybko! Mam dla was prezent na pożegnanie...', '', 0),
(26537, 'koKR', 'Wsparcie! Potrzebujemy wsparcia!', '', 0),
(26538, 'koKR', 'Pomocy, mon! Ich być za dużo!', '', 0),
(26932, 'koKR', 'Chłód, który czujecie, zwiastuje waszą zgubę!', '', 0),
(26933, 'koKR', 'Wzmocnijcie moją obronę! Prędzej, niech was licho!', '', 0),
(27777, 'koKR', 'Chyba widzicie, że to wszystko na próżno!', '', 0),
(28034, 'koKR', 'Wasze wysiłki... są daremne.', '', 0),
(28035, 'koKR', 'Taki los czeka każdego, kto sprzeciwi się Królowi Liszowi!', '', 0),
(29588, 'koKR', '%s wzywa pomocy!', '', 0),
(29606, 'koKR', 'Tharon\'ja widzi wszystko! Dzieło śmiertelników nie zakończy wiecznej dynastii!', '', 0),
(29611, 'koKR', 'Tak jak przepowiedział Tharon\'ja!', '', 0),
(29612, 'koKR', 'Tak, jak zostało zapisane!', '', 0),
(29613, 'koKR', 'Twoje ciało służy teraz Tharon\'ji!', '', 0),
(29614, 'koKR', 'Tharon\'ja znajdzie zastosowanie dla twojej śmiertelnej powłoki!', '', 0),
(29615, 'koKR', 'Nie! Ten smak... trwał zbyt krótko!', '', 0),
(29616, 'koKR', 'Aaach!! Tharon\'ja chce więcej!', '', 0),
(29617, 'koKR', 'To... niemożliwe! Tharon\'ja jest wieczny! Tharon\'ja... jest...', '', 0),
(30036, 'koKR', 'Poddajcie się wreszcie i gińcie!', '', 0),
(30041, 'koKR', 'Więcej flaków! Więcej krwi! Więcej żarcia!', '', 0),
(30042, 'koKR', 'Ja cię pokroić i zjeść!', '', 0),
(30043, 'koKR', 'Taki głodny! Musieć żreć!', '', 0),
(30044, 'koKR', 'Trup robić bum!', '', 0);
